import{_ as a,o as t,c as n,a3 as o}from"./chunks/framework.Dz5Q8p4s.js";const c=JSON.parse('{"title":"HACTS: a Human-As-Copilot Teleoperation System for Robot Learning","description":"","frontmatter":{"title":"HACTS: a Human-As-Copilot Teleoperation System for Robot Learning","arxiv":"2503.24070","date":"2025-03-31","authors":"Zhiyuan Xu, Yinuo Zhao, Kun Wu, Ning Liu, Junjie Ji, Zhengping Che, Chi Harold Liu, Jian Tang","categories":"cs.RO, cs.LG","topics":"遥操作, 人在回路学习, 动作修正数据","outline":[2,2]},"headers":[],"relativePath":"papers/2503.24070.md","filePath":"papers/2503.24070.md","lastUpdated":null}'),e={name:"papers/2503.24070.md"};function r(p,s,l,i,u,g){return t(),n("div",null,[...s[0]||(s[0]=[o('<h1 id="hacts-a-human-as-copilot-teleoperation-system-for-robot-learning" tabindex="-1">HACTS: a Human-As-Copilot Teleoperation System for Robot Learning <a class="header-anchor" href="#hacts-a-human-as-copilot-teleoperation-system-for-robot-learning" aria-label="Permalink to &quot;HACTS: a Human-As-Copilot Teleoperation System for Robot Learning&quot;">​</a></h1><table tabindex="0"><thead><tr><th>项</th><th>内容</th></tr></thead><tbody><tr><td><strong>arXiv</strong></td><td><a href="https://arxiv.org/abs/2503.24070" target="_blank" rel="noreferrer">2503.24070</a></td></tr><tr><td><strong>提交日期</strong></td><td>2025-03-31</td></tr><tr><td><strong>作者</strong></td><td>Zhiyuan Xu, Yinuo Zhao, Kun Wu, Ning Liu, Junjie Ji, Zhengping Che, Chi Harold Liu, Jian Tang</td></tr><tr><td><strong>分类</strong></td><td>cs.RO, cs.LG</td></tr><tr><td><strong>一句话</strong></td><td>用 247 美元的 3D 打印件加 Dynamixel 舵机做一套与 UR5 运动学等价的主从臂，并把从臂关节位置实时反向同步回主臂，使人能在策略自主执行途中随时无缝接管、顺带采集动作修正数据。</td></tr></tbody></table><blockquote><p><strong>所属教程</strong>：<a href="/notes/tutorials/embodied-ai-general">通用具身智能</a></p></blockquote><div class="tip custom-block"><p class="custom-block-title">版本说明</p><p>arXiv abs 页给出的 HTML 版本是 <strong>v2</strong>（v1 2025-03-31，v2 2025-12-15），本文按 v2 全文撰写。论文发表于 IROS 2025（DOI 10.1109/IROS60139.2025.11247309）。本站论文索引里该条目标题为空，实为 HACTS。</p></div><h2 id="§-1-—-研究问题与重要性" tabindex="-1">§ 1 — 研究问题与重要性 <a class="header-anchor" href="#§-1-—-研究问题与重要性" aria-label="Permalink to &quot;§ 1 — 研究问题与重要性&quot;">​</a></h2><p>遥操作硬件在机器人学习里承担两件事：采演示、以及在人在回路的训练中接管。第一件事已经被 ALOHA、GELLO 这类低成本运动学等价主从臂解决得相当好——它们比 VR、手柄、SpaceMouse 更精确，因为不必经过 IK 与运动规划这层损耗。</p><p>第二件事没有被解决。ALOHA 和 GELLO 都是<strong>单向</strong>的：人推主臂，从臂跟随；但当从臂正被策略模型驱动时，主臂完全不知道从臂在哪。此时人若要接管，主臂与从臂之间存在一个任意大的位姿差，一旦切换控制权，从臂会猛地跳向主臂当前位置。论文用了一个很到位的类比：这就像自动驾驶时方向盘不跟着轮子转，司机想接管的瞬间必然失控。</p><p>已有的双向遥操作方案（FACTR、Bi-ACT、力反馈式系统）走的是力/触觉反馈路线，需要从臂能提供精确的力或触觉信息——UR5 这类最常见的工业臂做不到，而且这些系统多数只在同构主从（同一款臂做主、做从）上验证过。所以缺的是一个<strong>只依赖关节位置、因而几乎兼容所有机械臂</strong>的双向同步方案。这件事的价值不在硬件本身，而在它解锁的数据类型：人在策略失败的那一刻接管，产生的是&quot;从失败状态恢复&quot;的动作修正数据，这类数据在现有的以成功轨迹为主的数据集里是缺失的。</p><h2 id="§-2-—-前人工作与不足" tabindex="-1">§ 2 — 前人工作与不足 <a class="header-anchor" href="#§-2-—-前人工作与不足" aria-label="Permalink to &quot;§ 2 — 前人工作与不足&quot;">​</a></h2><p><strong>末端位姿类遥操作</strong>（VR、手柄、手机、SpaceMouse）：只能控末端 6-DoF，依赖 IK/FK 与运动规划，人的意图被中间层削掉，尤其在需要特定关节构型避障时无法表达。</p><p><strong>运动学等价主从臂</strong>（ALOHA、GELLO）：精度和表达力都好，成本低，已经成为事实标准。但都是单向控制，无法在自主执行中安全接管。</p><p><strong>双向控制系统</strong>（FACTR、Bi-ACT、力反馈遥操作）：能提供力或触觉反馈，但要求从臂侧有力/触觉传感能力，硬件成本与算法复杂度都高；Bi-ACT 虽然可以不用力反馈，却只在同构主从上测过，向 UR5 这类常见平台的可迁移性未知。</p><p><strong>人在回路学习方法</strong>（HG-DAgger、IWR、HACO、HIL-SERL）：算法侧已经证明主动人工干预能大幅提升 RL 的样本效率与安全性，但它们都默认存在一套&quot;灵活、及时&quot;的干预硬件——这个前提正是本文要补的。论文也点名了并行工作 RoboCopilot 提出了类似的人在回路遥操作设置，本文的增量是补上了一个 RL 的实现。</p><h2 id="§-3-—-重建作者的思考路径" tabindex="-1">§ 3 — 重建作者的思考路径 <a class="header-anchor" href="#§-3-—-重建作者的思考路径" aria-label="Permalink to &quot;§ 3 — 重建作者的思考路径&quot;">​</a></h2><p>从一个具体的失败模式出发：用 GELLO 采完数据、训好 ACT、让它自主跑，人站在旁边看着它抓偏了想救一把，却发现没法救——主臂还停在上次松手的位置。这个体验直接指向&quot;主从之间缺一条反向链路&quot;。</p><p>接下来是找最便宜的实现。力反馈需要从臂有力传感，UR5 没有；但<strong>关节位置</strong>是所有机械臂都对外暴露的量。既然主臂用的是 Dynamixel 舵机，而舵机本来就同时支持位置读取与位置控制，那么把从臂的关节角经过反向偏移补偿后写回舵机，就得到了双向同步——几乎零额外硬件成本，只是把已有硬件的另一半能力用起来。</p><p>再往下是模式切换：需要一个不占手的开关，脚踏板是最直接的选择。</p><p>最后是验证设计。要证明这套硬件有用，最省事的方式不是测硬件指标（接管延迟、跟随误差），而是测它产出的数据的下游价值：用它采修正数据、训 ACT/DP、看成功率。这条路径解释了为什么全文没有任何硬件层面的定量指标。</p><h2 id="§-4-—-核心-intuition" tabindex="-1">§ 4 — 核心 Intuition <a class="header-anchor" href="#§-4-—-核心-intuition" aria-label="Permalink to &quot;§ 4 — 核心 Intuition&quot;">​</a></h2><p>单向遥操作在&quot;人看着机器人自己动&quot;的场景里是断链的：人手里的设备与机器人的状态无关，接管必然伴随一次跳变。只要让从臂的关节位置实时写回主臂，主从就始终处在同一构型上，接管在物理上退化成&quot;人开始施加力&quot;这一个连续过程，不需要任何模式切换的对齐动作。这条链路本身不需要力传感，因此可以挂在任何能读关节角的机械臂上。</p><h2 id="§-5-—-具体方法与完整-pipeline" tabindex="-1">§ 5 — 具体方法与完整 Pipeline <a class="header-anchor" href="#§-5-—-具体方法与完整-pipeline" aria-label="Permalink to &quot;§ 5 — 具体方法与完整 Pipeline&quot;">​</a></h2><p><strong>硬件</strong>（表 I，总价 247 美元）：前三个负载较大的连杆用 Dynamixel XL430-W250-T（2 个，100 美元），夹爪与其余连杆用 XL330-M288-T（5 个，120 美元），加 12V 5A 电源、WaveShare 总线舵机适配器、降压模块、3D 打印 PLA 结构件。结构按 UR5 的 DH 参数等比缩放，复用并改造了 GELLO 的部分设计以适配 XL430。此处有一处不一致：正文写&quot;前三个连杆用 XL430&quot;，而表 I 里 XL430 的数量是 2。</p><p><strong>软件</strong>：Dynamixel API 直接读写舵机位置。正向（采数据）：读主臂位置 → 偏移标定 → 发给机器人控制器。反向（自主执行）：读机器人位置 → 反向偏移补偿 → 写回舵机。脚踏板作为手动接管开关，在自主与干预两种模式间切换。</p><p><strong>实验平台</strong>：两个工作站，各配一个腕部相机与一到多个第三人称相机，UR5 + Robotiq 2f-85 夹爪，全部跑在一台 RTX 4090 上。</p><p><strong>模仿学习流程</strong>（以 UprightMug 为例：把倒扣的杯子翻正并放回中心位置）：先用 HACTS 采 100 条专家演示；随机取 50 条训出 pre-ACT/pre-DP；用全部 100 条训出 full-ACT/full-DP 作为等数据量基线；让 pre-模型自主执行，人在需要时踩脚踏板接管，采 50 条干预轨迹；把这 50 条与最初的 50 条专家轨迹混合训出 HACTS-ACT/DP。四种设定分别对应四种采集干预数据的时机：EADC（无论成败，机器人执行到一定进度就开始录）、FCID（分布内但 pre-模型失败的场景）、ODSS（物体摆放完全超出训练分布的静态场景）、ODDS（执行中人为把目标物体挪走的动态场景）。ODDS 用 DP 而非 ACT，理由是 ACT 的动作分块在时间维度上做了聚合，天然不适合动态任务。每个实验取验证损失最低的检查点，做 10 次 rollout。</p><p><strong>RL 流程</strong>（RLPD-HACTS，任务 CloseBin：关一个随机摆放和朝向的垃圾桶盖）：三阶段。先用 HACTS 采 200 个任务完成的正样本与约 1000 个负样本，训一个基于预训练 ResNet-10 的二分类奖励器（读前视与腕部相机）。再采 20 条专家轨迹训 BC 策略，输入是 ResNet-10 嵌入 + 夹爪状态 + 相对初始位姿的 6D 本体感知，动作是末端 6D 增量与夹爪状态。最后加载 actor 权重用 RLPD 在线微调，训练中人通过 HACTS 做短促频繁的修正，环境 10 Hz。</p><h2 id="§-6-—-核心数学推导" tabindex="-1">§ 6 — 核心数学推导 <a class="header-anchor" href="#§-6-—-核心数学推导" aria-label="Permalink to &quot;§ 6 — 核心数学推导&quot;">​</a></h2><p>本文无形式化数学推导，跳过。</p><h2 id="§-7-—-实验设计与结论" tabindex="-1">§ 7 — 实验设计与结论 <a class="header-anchor" href="#§-7-—-实验设计与结论" aria-label="Permalink to &quot;§ 7 — 实验设计与结论&quot;">​</a></h2><p><strong>问题一：HACTS 采的干预数据能否顶替等量专家演示？</strong> EADC 设定，表 II（ACT，每格 10 次 rollout）：OpenBox pre 50% / full 60% / HACTS 80%；SteamBun 60 / 80 / 90；UprightMug 40 / 60 / 70。在相同总数据量（100 条）下，HACTS-ACT 三个任务全部高于 full-ACT，各高 10 个百分点——也就是每个任务多成功 1 次。作者的解释是干预数据集中在 pre-模型常失败的环节（如抓取）上。</p><p><strong>问题二：修正数据能否在分布内提升成功率？</strong> FCID：OpenBox 10 / 40 / 50；SteamBun 20 / 60 / 80；UprightMug 10 / 40 / 70。相对 full-ACT 分别 +10、+20、+30 个点。这里需要注意 FCID 的定义是&quot;物体摆在训练分布内、但 pre-模型仍失败的场景&quot;，而 pre-ACT 在这些场景上仍报出 10%/20%/10% 的成功率，与&quot;这些是失败场景&quot;的定义并不严格自洽（推测是同一批场景重新评测时的随机性）。</p><p><strong>问题三：能否改善分布外泛化？</strong> ODSS（静态 OOD）：三个任务上 pre-ACT 与 full-ACT <strong>全部为 0%</strong>，HACTS-ACT 分别拿到 30% / 50% / 40%。ODDS（动态 OOD，执行中挪走物体，用 DP）表 III 只有 OpenBox 一行：pre-DP 0% / full-DP 0% / HACTS-DP 40%。这是全文数字最醒目的一组，但也是解释最需要小心的一组（见 §11）。</p><p><strong>问题四：能否支撑在线 RL？</strong> 表 IV：CloseBin 任务，10 分钟离线预训练 + 45 分钟在线训练，成功率 50% → 80%，回合长度 32 → 19 步（10 次试验）。图 6 给出人工干预长度的变化：初期上升（Q 网络学习与探索导致性能下滑，需要长干预兜底），随后下降，最终稳定在 6 步以下，转为细粒度修正。这条曲线是全文关于&quot;接管质量&quot;最直接的证据。</p><p>需要如实记录的规模限制：模仿学习部分每格 10 次 rollout，因此表 II/III 的最小刻度是 10 个百分点；无种子重复、无误差棒；RL 部分同样是 10 次试验、单任务、单次运行。全文没有任何硬件层面的定量指标——接管延迟、主从跟随误差、切换瞬间的力/加速度突变都没有测量，奖励分类器的准确率与假阳性率也未报告。</p><h2 id="§-8-—-take-aways" tabindex="-1">§ 8 — Take-aways <a class="header-anchor" href="#§-8-—-take-aways" aria-label="Permalink to &quot;§ 8 — Take-aways&quot;">​</a></h2><p><strong>5 句话版</strong>：单向遥操作硬件在&quot;人接管正在自主执行的机器人&quot;这个场景里是断链的，因为主臂不知道从臂在哪，切换控制权必然产生跳变。HACTS 用 247 美元的 3D 打印件加 Dynamixel 舵机做出运动学等价主臂，并把从臂关节角实时反向同步回主臂，只依赖位置信息、因此几乎兼容所有机械臂。用它采集的动作修正数据在三个 UR5 任务上让 ACT 全面超过等数据量的纯专家演示（EADC 三项各 +10 点，FCID 最多 +30 点）。在分布外场景上，纯演示训练的模型全部为 0%，加入修正数据后达到 30–50%。它还能支撑 RLPD 式在线 RL：CloseBin 任务 55 分钟内从 50% 到 80%，人工干预长度随训练自然衰减到 6 步以下。</p><p><strong>3 句话版</strong>：把主从遥操作从单向变成关节位置双向同步，人就能在策略自主执行中无缝接管并顺手采集修正数据。三个真机任务上，同等数据量下修正数据优于纯专家演示，且是唯一能处理分布外摆放的数据来源。硬件成本 247 美元，且不需要力/触觉传感。</p><p><strong>1 句话版</strong>：给遥操作装上反向同步，人就从&quot;演示者&quot;变成了&quot;副驾驶&quot;。</p><h2 id="§-9-—-最脆弱的假设" tabindex="-1">§ 9 — 最脆弱的假设 <a class="header-anchor" href="#§-9-—-最脆弱的假设" aria-label="Permalink to &quot;§ 9 — 最脆弱的假设&quot;">​</a></h2><p><strong>&quot;关节位置的双向同步足以支撑及时、安全的接管&quot;。</strong> 整个硬件贡献建立在这一条上：正因为只需要位置，方案才便宜且通用；正因为位置同步消除了跳变，接管才被称为&quot;无缝&quot;。</p><p>它可能不成立的原因是，接管的瓶颈未必在&quot;主臂在哪&quot;。人决定介入的时刻取决于<strong>预判</strong>——看出机器人将要抓偏、将要撞上、力过大——而位置同步只解决了介入之后的执行连续性，没有给人任何关于&quot;即将发生什么&quot;的信息。更具体地，位置同步的主臂在人不施力时是被舵机主动驱动的，人手搭在上面会感到明显的阻抗；此时人要施加多大力才算&quot;接管&quot;、以及舵机在人抵抗时的力矩表现如何，全文没有描述。若接管仍需明显的握持力与反应时间，那么一个更简单的方案——单向 GELLO 加一个&quot;接管前先把主臂对齐到从臂当前位姿&quot;的软件流程，或干脆让主臂在自主模式下重力补偿自由浮动——可能达到同样效果，硬件贡献就被抹平了。</p><p>论文为这条假设提供的直接证据只有一条，而且是间接的：图 6 显示 RL 训练后期人工干预长度稳定在 6 步以下（10 Hz 下约 0.6 秒），说明细粒度短干预确实可行。这是有价值的证据，但它证明的是&quot;能做短干预&quot;，不是&quot;位置同步是短干预的必要条件&quot;。论文缺的是最基本的硬件测量：接管延迟、切换瞬间从臂的加速度/力矩尖峰，以及与单向硬件的同项对比。</p><h2 id="§-10-—-最小复现实验" tabindex="-1">§ 10 — 最小复现实验 <a class="header-anchor" href="#§-10-—-最小复现实验" aria-label="Permalink to &quot;§ 10 — 最小复现实验&quot;">​</a></h2><p>一周内可做，不需要复现 RL 部分：</p><ul><li>硬件侧准备两种模式，跑在同一套 HACTS 上，因此不需要额外制造设备：<strong>A 模式</strong>为论文的持续反向同步；<strong>B 模式</strong>为单向控制，反向同步全程关闭，仅在踩下脚踏板的瞬间把主臂舵机一次性伺服到从臂当前位姿再交出控制权（GELLO + 对齐这一最朴素的替代方案）。</li><li>用同一个 pre-ACT 检查点，在 OpenBox 上各采 50 条干预轨迹，分别混合最初的 50 条专家演示训练，各评 30 次 rollout（把刻度从 10% 降到 3.3%）。</li><li>同时记录三项硬件指标：从踩下脚踏板到从臂进入人控轨迹的时间；切换后 0.5 秒内从臂关节速度的峰值；操作者主观的接管顺畅度打分。</li><li><strong>判据</strong>：若 B 模式的下游成功率与 A 模式在统计上不可区分（差距小于两个标准误），则位置同步的价值主要是操作体验而非数据质量，硬件贡献需要重新表述；若 A 显著更好且伴随更低的速度峰值，则 §9 的担忧被排除，且顺带补上了论文缺失的硬件量化证据。</li></ul><h2 id="§-11-—-最强反例设计" tabindex="-1">§ 11 — 最强反例设计 <a class="header-anchor" href="#§-11-—-最强反例设计" aria-label="Permalink to &quot;§ 11 — 最强反例设计&quot;">​</a></h2><p>最有力的攻击针对 ODSS 与 ODDS 这两组最醒目的结果（0% → 30–50%）。这两组的实验设计使 HACTS 几乎不可能不赢，理由有两层。</p><p>第一层，基线的 0% 是<strong>由构造保证的</strong>：pre-模型与 full-模型的全部 100 条训练数据都在分布内采集，而评测在分布外进行；ODSS 的场景本来就是按&quot;pre-模型性能显著下滑&quot;挑出来的。第二层更关键，那 50 条修正轨迹是<strong>在被评测的同一个 OOD 场景里采的</strong>。也就是说，训练分布被扩展到了包含测试分布，而基线的训练分布没有。这不是泛化，是补数据。</p><p>因此存在一个完整的替代解释：把任何 50 条在目标场景采集的数据加进去都会让 0% 变成非零，与它是不是&quot;修正数据&quot;、是不是用双向硬件采的都无关。</p><p><strong>判决实验</strong>：加一个算力与数据量匹配的 arm——用<strong>单向</strong>遥操作（不用干预，直接从零示教）在同样的 OOD 摆放区域采 50 条<strong>普通专家演示</strong>，与最初 50 条混合训练。若该 arm 也达到 30–50%，那么表 II 的 ODSS 行证明的只是&quot;在测试分布上采数据有用&quot;这一平凡结论。要让论文的主张成立，需要 HACTS 的修正数据在<strong>同等采集时间</strong>下明显优于同区域的普通演示——修正数据的采集本身更快（只录失败后的片段而非整条轨迹），这才是它真正可能的优势，而论文从未从这个角度做过比较，也没有报告两种方式的采集耗时。</p><p>第二条攻击线更简单：所有格子都是 10 次 rollout。EADC 的三个 +10 点各自等于 1 次成功之差，在二项分布下（<span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.4306em;"></span><span class="mord mathnormal">n</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:0.6444em;"></span><span class="mord">10</span></span></span></span>）完全落在噪声内。要支撑&quot;HACTS 数据可替代专家数据&quot;这一结论，至少需要每格 30–50 次试验与多种子重复。</p><h2 id="§-12-—-follow-up-research-idea" tabindex="-1">§ 12 — Follow-up Research Idea <a class="header-anchor" href="#§-12-—-follow-up-research-idea" aria-label="Permalink to &quot;§ 12 — Follow-up Research Idea&quot;">​</a></h2><p><strong>(a) 驱动局限</strong>：HACTS 目前只在人<strong>决定介入</strong>时才产生数据，其余时间那条反向链路的信息被丢弃。但双向同步意味着，只要人把手轻搭在主臂上，系统在每一个时刻都能读到&quot;人的手想去哪&quot;与&quot;机器人正要去哪&quot;之间的差值——一个稠密的、逐时刻的人机分歧信号。现在这个信号只在越过某个阈值（人踩下脚踏板）时被离散化成一次二值事件，绝大部分带宽被浪费。</p><p><strong>(b) 新的 framing 与可借鉴工具</strong>：把遥操作硬件从&quot;演示采集器&quot;重新定义为<strong>稠密偏好/风险传感器</strong>。人不接管、只是握着主臂旁观时，主从位置残差 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mord">∥</span><span class="mord"><span class="mord"><span class="mord"><span class="mord boldsymbol" style="margin-right:0.037em;">q</span></span></span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.242em;"><span style="top:-2.4559em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord text mtight"><span class="mord mtight">leader</span></span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.2441em;"><span></span></span></span></span></span></span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">−</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mord"><span class="mord"><span class="mord"><span class="mord boldsymbol" style="margin-right:0.037em;">q</span></span></span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.242em;"><span style="top:-2.4559em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord text mtight"><span class="mord mtight">follower</span></span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.2441em;"><span></span></span></span></span></span></span><span class="mord">∥</span></span></span></span> 及其时间导数构成一条连续标注流。这条流的语义接近逆强化学习里的&quot;专家会怎么做&quot;，但成本远低——不需要人完整演示，只需要人跟着看。可直接借用的工具有两类：一是偏好式 RL 里从稠密比较信号学奖励的方法（把残差当作逐步的软偏好而非 episode 级标签）；二是共享自治与故障预测里的残差监控框架，把残差当作一个在线的分布外/风险检测器。</p><p><strong>(c) 第一个实验</strong>：让操作者在策略自主执行 OpenBox 与 UprightMug 时全程轻握主臂但<strong>不踩脚踏板</strong>，记录每一步的主从位置残差与最终成败。检验两件事：残差是否在失败发生前就显著上升（画残差-时间曲线与失败时刻对齐，算提前量）；以及用残差作为唯一特征训一个失败预测器，其 ROC-AUC 是多少。若残差能提前 1 秒以上预警失败，就立刻得到两个下游产物——一个不需要视觉奖励分类器的在线安全监控器（可直接替换 RLPD-HACTS 里那个用 200 正样本 + 1000 负样本训的 ResNet-10），以及一个把&quot;人只需旁观&quot;变成有效监督的新数据采集范式。</p>',55)])])}const m=a(e,[["render",r]]);export{c as __pageData,m as default};
